/**
 * Completeness invariant for the EVENT catalog — NO database.
 *
 * src/lib/api-auth/event-catalog.ts (generated by scripts/gen-event-catalog.mjs)
 * is the runtime list the admin « Évènements » tab + docs render, since the
 * EventMap in src/events/types.ts is a TYPE with no runtime form. This test
 * re-parses the EventMap keys from types.ts and asserts the catalog lists EXACTLY
 * that set + that every catalogued event resolves to a real severity.
 *
 * Run:
 *   pnpm exec tsx --conditions=react-server src/lib/db/tests/event-catalog.test.ts
 */
import { readFileSync } from "node:fs";
import { join } from "node:path";

import { EVENT_NAMES, EVENT_CATALOG } from "@/lib/api-auth/event-catalog";
import { severityFor } from "@/events/severity";

let passed = 0;
let failed = 0;
function check(label: string, cond: boolean) {
  if (cond) {
    passed++;
    console.log(`  ✓ ${label}`);
  } else {
    failed++;
    console.error(`  ✗ ${label}`);
  }
}

function diskEvents(): Set<string> {
  const src = readFileSync(join(process.cwd(), "src", "events", "types.ts"), "utf8");
  const re = /^\s*"([a-z][a-z0-9_]*(?:\.[a-z0-9_]+)+)":/gm;
  return new Set([...src.matchAll(re)].map((m) => m[1]));
}

function main() {
  const disk = diskEvents();
  const catalog = new Set(EVENT_NAMES);

  console.log("event-catalog ⇔ events/types.ts:");
  check(`types.ts has events (${disk.size})`, disk.size > 100);
  check(`catalog non-empty (${catalog.size})`, catalog.size > 0);

  const missing = [...disk].filter((n) => !catalog.has(n)).sort();
  check(`every EventMap key is catalogued${missing.length ? ` — MISSING: ${missing.join(", ")}` : ""}`, missing.length === 0);

  const extra = [...catalog].filter((n) => !disk.has(n)).sort();
  check(`no phantom catalog events${extra.length ? ` — EXTRA: ${extra.join(", ")}` : ""}`, extra.length === 0);

  const dup = EVENT_NAMES.filter((n, i) => EVENT_NAMES.indexOf(n) !== i);
  check(`no duplicate catalogued events${dup.length ? ` — ${[...new Set(dup)].join(", ")}` : ""}`, dup.length === 0);

  // Every domain bucket's `domain` is the events' shared first segment.
  const badGroup = EVENT_CATALOG.filter((g) => g.events.some((e) => e.split(".")[0] !== g.domain));
  check(`every event sits under its domain bucket${badGroup.length ? ` — ${badGroup.map((g) => g.domain).join(", ")}` : ""}`, badGroup.length === 0);

  // Every domain has a human (French) label — the generator falls back to the raw
  // domain key when DOMAIN_LABELS in scripts/gen-event-catalog.mjs lacks it.
  const unlabeled = EVENT_CATALOG.filter((g) => !g.label || g.label === g.domain);
  check(`every domain has a label${unlabeled.length ? ` — MISSING in DOMAIN_LABELS: ${unlabeled.map((g) => g.domain).join(", ")}` : ""}`, unlabeled.length === 0);

  // severityFor resolves a known level for every event.
  const LEVELS = new Set(["debug", "info", "warn", "error"]);
  const badSev = EVENT_NAMES.filter((n) => !LEVELS.has(severityFor(n)));
  check(`severityFor resolves for every event${badSev.length ? ` — ${badSev.slice(0, 5).join(", ")}` : ""}`, badSev.length === 0);

  console.log(`\n=== done: ${passed} passed, ${failed} failed === (disk=${disk.size}, catalog=${catalog.size})`);
  if (failed > 0) process.exit(1);
}

main();
